$candidatesOutsideQueue = Get-ChildItem -LiteralPath $root -Recurse -File -Include *.md | ForEach-Object {
  $content = Get-Content -LiteralPath $_.FullName -Raw
  $type = if ($content -match '(?m)^type:\s*["'']?([^"''\r\n]+)') { $Matches[1].Trim() } else { '' }
  if ($_.FullName.Substring($root.Length).TrimStart('\') -notlike 'Content_Candidates*' -and $type -eq 'research_content_candidate') { $_.FullName.Substring($root.Length).TrimStart('\') }
}
if ($candidatesOutsideQueue) { $candidatesOutsideQueue } else { 'No research_content_candidate files outside Content_Candidates.' }
}

content.title:
& {
$root = "C:\Users\CaveUser\Documents\Obsidian Vault\The Research Spine\03_References"
Get-ChildItem -LiteralPath $root -Recurse -File | Group-Object { $_.DirectoryName.Substring($root.Length).TrimStart('\').Split('\')[0] } | Sort-Object Count -Descending | ForEach-Object { [PSCustomObject]@{ Area = if ($_.Name) { $_.Name } else { '(root)' }; Count=$_.Count; TotalKB=[math]::Round(($_.Group | Measure-Object Length -Sum).Sum / 1KB, 1) } } | Format-Table -AutoSize
}

